contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) public payable {
        require(true);

        // First authorized write.
        c.setLimits(maxMultiplier, minMultiplier, rate);
        uint256 beforeMax = c.maxMultiplier();
        uint256 beforeMin = c.minMultiplier();
        uint256 beforeRate = c.rate();

        // Second authorized write with the same parameters; must not revert unexpectedly.
        bool reverted;
        try c.setLimits(maxMultiplier, minMultiplier, rate) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterMax = c.maxMultiplier();
        uint256 afterMin = c.minMultiplier();
        uint256 afterRate = c.rate();

        assert(!reverted && afterMax == beforeMax && afterMin == beforeMin && afterRate == beforeRate);
    }

    receive() external payable {}
}

