contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 maxMultiplier,
        uint256 minMultiplier,
        uint256 rateValue,
        address asset,
        uint256 slope0,
        uint256 slope1
    ) public payable {
        require(maxMultiplier > 0 && minMultiplier > 0, "limits must be positive");
        require(maxMultiplier >= minMultiplier, "max >= min");
        require(rateValue > 0, "rate must be positive");
        require(slope0 > 0 && slope1 >= 0, "slopes non-negative");

        // Setup: set limits and slopes. All state-changing calls are top-level.
        c.setLimits(maxMultiplier, minMultiplier, rateValue);
        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({
            kink: 5e26,
            slope0: slope0,
            slope1: slope1
        });
        c.setSlopes(asset, slopes);

        // Read state before the deciding call.
        uint256 beforeMax = maxMultiplier;
        uint256 beforeMin = minMultiplier;

        // Deciding call: rate on some vault (any vault) and asset.
        address vault = address(0x1234567890123456789012345678901234567890);
        uint256 returnedRate = c.rate(vault, asset);

        // Read the multiplier that was stored by the call.
        // The multiplier is stored in the public getter of utilizationData? Not directly accessible, but the
        // effect is observable through the return value and the fact that it must be within limits.
        // However, the multiplier itself is not directly exposed. The rule must use the returned rate and
        // the fact that the multiplier must be within limits. We can assert that the returned rate is
        // consistent with the multiplier being clamped. Since we can't read multiplier directly, we
        // assert that the returned rate is not absurd: for a utilization <= kink, the multiplier is
        // clamped to >= minMultiplier, so the interest rate is >= (slope0 * utilization / kink) * minMultiplier / 1e27.
        // But we don't know utilization. However, we can assert that the returned rate is bounded by
        // the theoretical max: for utilization <= kink, max multiplier = maxMultiplier (since it might start
        // at maxMultiplier? Actually multiplier could be anything initially? It starts at 0? Wait, utilizationData.multiplier
        // is initialized to 0. Then after the call, if utilization > kink, multiplier is multiplied and then clamped to max.
        // If utilization <= kink, multiplier = multiplier * 1e27 / (something) then clamped to min.
        // Initially multiplier = 0, so for utilization <= kink, multiplier becomes 0 * ... = 0, then clamped to min.
        // So the multiplier after the first call will be min (if utilization <= kink) or max (if utilization > kink)?
        // More precisely, for utilization > kink, multiplier = 0 * (1e27+...) / 1e27 = 0, then clamped to max? No: 0 * something = 0, then if 0 > max? No, 0 < max, so it stays 0. Then interestRate = (slope0 + slope1*excess/1e27) * 0 / 1e27 = 0.
        // So on first call, multiplier may be 0 if utilization > kink. That's not clamped to max.
        // So the rule about multiplier being within [min, max] after call holds only if multiplier was non-zero before.
        // But we can still assert a general property: the returned rate is either 0 (if multiplier became 0) or >= (slope0*utilization/kink) * minMultiplier / 1e27 for utilization <= kink.
        // Since we don't know utilization, we can assert that returned rate is <= (slope0 + slope1) * maxMultiplier / 1e27.
        // That's a general bound: interestRate = (slope0 + slope1*excess/1e27) * multiplier / 1e27 <= (slope0+slope1) * maxMultiplier / 1e27.
        // And for utilization <= kink, interestRate = (slope0 * utilization / kink) * multiplier / 1e27 <= slope0 * maxMultiplier / 1e27 <= (slope0+slope1)*maxMultiplier/1e27.
        // So a general upper bound holds.
        uint256 upperBound = (slope0 + slope1) * beforeMax / 1e27;
        assert(returnedRate <= upperBound);
    }

    receive() external payable {}
}

