pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C();
    }

    function _run(address asset, uint256 kink, uint256 slope0, uint256 slope1, address accessControl) internal {
        try c.initialize(accessControl) {} catch { return; }
        bool reverted;
        try c.setSlopes(asset, IVaultAdapter.SlopeData(kink, slope0, slope1)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool validKink = kink != 0 && kink < 1e27;
        assertTrue(validKink || reverted);
    }

    function testFuzz_run(address asset, uint256 kink, uint256 slope0, uint256 slope1, address accessControl) public {
        vm.assume(asset.code.length == 0 && uint160(asset) > 0xffff && asset != address(this) && asset != address(c) && asset != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && asset != 0x000000000000000000636F6e736F6c652e6c6f67 && asset != 0x4e59b44847b379578588920cA78FbF26c0B4956C && asset != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(accessControl.code.length == 0 && uint160(accessControl) > 0xffff && accessControl != address(this) && accessControl != address(c) && accessControl != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && accessControl != 0x000000000000000000636F6e736F6c652e6c6f67 && accessControl != 0x4e59b44847b379578588920cA78FbF26c0B4956C && accessControl != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(asset, kink, slope0, slope1, accessControl);
    }

    receive() external payable {}
}

